"use client"

import { Button } from "@/components/ui/button"
import type { Session } from "@/lib/types"

interface SessionHeaderProps {
  session: Session
  connectionState: "connecting" | "connected" | "disconnected"
  onEndSession: () => void
  onGenerateSummary: () => void
}

export function SessionHeader({ session, connectionState, onEndSession, onGenerateSummary }: SessionHeaderProps) {
  const connectionConfig = {
    connecting: { color: "bg-amber-500", text: "Connecting..." },
    connected: { color: "bg-emerald-500", text: "Live" },
    disconnected: { color: "bg-destructive", text: "Disconnected" },
  }

  const config = connectionConfig[connectionState]

  return (
    <header className="bg-card border-b-2 border-border px-4 py-3">
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        <div className="flex items-center gap-4">
          <div className="w-10 h-10 rounded-sm border-2 border-primary flex items-center justify-center">
            <span className="text-lg font-mono font-bold text-primary">AF</span>
          </div>
          <div>
            <h1 className="text-lg font-serif font-semibold">{session.title}</h1>
            <div className="flex items-center gap-2 text-xs text-muted-foreground">
              <span className="font-mono">ID: {session.id}</span>
              <span>|</span>
              <span>{session.participant_count} participants</span>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 px-3 py-1.5 bg-background border rounded-sm">
            <span
              className={`w-2 h-2 rounded-full ${config.color} ${connectionState !== "connected" ? "animate-pulse" : ""}`}
            />
            <span className="text-xs font-mono uppercase tracking-wider">{config.text}</span>
          </div>
          <Button variant="outline" size="sm" onClick={onGenerateSummary}>
            Summary
          </Button>
          <Button variant="destructive" size="sm" onClick={onEndSession}>
            End Session
          </Button>
        </div>
      </div>
    </header>
  )
}
